def ret_of(pair):
    return pair[1]

def best_worst_from_csv(text):
    rows = []
    for line in text.strip().split("\n")[1:]:
        date, close = line.strip().split(",")
        rows.append((date, float(close)))
    rets = [(d1, (c1 - c0) / c0) for (d0, c0), (d1, c1) in zip(rows, rows[1:])]
    best, _ = max(rets, key=ret_of)
    worst, _ = min(rets, key=ret_of)
    return (best, worst)
